-- ----------------------------
-- Table structure for blogs
-- ----------------------------
DROP TABLE IF EXISTS `blogs`;
CREATE TABLE `blogs`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `thumbnail` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
  `slug` varchar(125) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `title` varchar(75) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `description` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
  `content` blob NULL,
  `category` varchar(25) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `tags` json NULL,
  `publish_at` datetime NULL DEFAULT NULL,
  `status` enum('Draft','Review','Publish','Archived') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT 'Draft',
  `created_at` datetime NULL DEFAULT NULL,
  `created_by` int NULL DEFAULT NULL,
  `updated_at` datetime NULL DEFAULT NULL,
  `updated_by` int NULL DEFAULT NULL,
  `deleted_at` datetime NULL DEFAULT NULL,
  `deleted_by` int NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of blogs
-- ----------------------------
INSERT INTO `blogs` VALUES (1, 'assets/uploads/blogs/35674-15889.jpg', 'memahami-peran-seo-dalam-strategi-pemasaran-digital', 'Memahami Peran SEO dalam Strategi Pemasaran Digital', 'Pemasaran digital telah menjadi inti dari upaya promosi bisnis di era digital ini. Dalam konteks ini, Search Engine Optimization (SEO) muncul sebagai elemen kunci yang membentuk landasan untuk strategi pemasaran digital yang sukses.', , 'SEO', '[\"seo\", \"optimation\", \"website\", \"marketing\"]', '2024-01-22 13:42:40', 'Publish', '2024-01-22 13:42:40', 1, '2024-01-23 08:33:08', NULL, NULL, NULL);
INSERT INTO `blogs` VALUES (2, 'assets/uploads/blogs/60f8a007e2f9cc.jpeg', 'pentingnya-penelitian-kata-kunci-dalam-strategi-seo-anda', 'Pentingnya Penelitian Kata Kunci dalam Strategi SEO Anda', 'Pada era digital yang penuh persaingan ini, keberadaan website tidak lagi cukup untuk mencapai keberhasilan online. Pentingnya penelitian kata kunci dalam strategi SEO menjadi krusial bagi setiap pemilik bisnis dan pemasar digital.', , 'SEO', '[\"Seo\", \"Website\", \"Digital\", \"Strategi\"]', '2024-01-23 08:33:08', 'Publish', '2024-01-22 21:54:08', 1, '2024-01-23 08:33:08', 1, NULL, NULL);
INSERT INTO `blogs` VALUES (3, 'assets/uploads/blogs/6190635a3a65e4.jpeg', 'jasa-pembuatan-website-mlm-profesional--solusi-terbaik-untuk-bisnis-anda', 'Jasa Pembuatan Website MLM Profesional: Solusi Terbaik untuk Bisnis Anda', 'Dalam era digital yang terus berkembang, memiliki kehadiran online adalah suatu keharusan bagi setiap bisnis, termasuk bisnis Multi Level Marketing (MLM). Jasa pembuatan website MLM menjadi solusi tepat bagi perusahaan yang ingin mengembangkan jaringan dan menjangkau lebih banyak konsumen. Dengan website yang profesional dan fungsional, bisnis MLM Anda dapat tumbuh lebih cepat dan lebih efektif.', , 'MLM', '[\"Jasa\", \"Pembuatan\", \"Website\", \"MLM\", \"Binary\", \"Matahari\"]', '2024-05-22 07:52:04', 'Publish', '2024-05-22 07:52:05', 1, '2024-01-23 08:33:08', NULL, NULL, NULL);

